import{_ as a,c as t,o as r,ag as o}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Research Template","description":"","frontmatter":{"title":"Research Template"},"headers":[],"relativePath":"research/research-template.md","filePath":"research/research-template.md","lastUpdated":null}'),s={name:"research/research-template.md"};function i(n,e,l,h,c,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="research-template" tabindex="-1">Research Template <a class="header-anchor" href="#research-template" aria-label="Permalink to &quot;Research Template&quot;">​</a></h1><h2 id="research-toolkit-templates" tabindex="-1">Research Toolkit Templates <a class="header-anchor" href="#research-toolkit-templates" aria-label="Permalink to &quot;Research Toolkit Templates&quot;">​</a></h2><p>Welcome to the comprehensive suite of research toolkit templates built on Cryptpad. These templates provide a foundation for collaborative research efforts, guiding teams through the planning, gathering, processing, and analysis phases. Each template is designed to be flexible and can be customized to fit the specific needs of your research project.</p><p>Cryptpad is a privacy-focused, self-hosted, collaborative, end-to-end encrypted (E2EE) platform that allows teams to work together on documents, spreadsheets, and other tools in real-time. It’s designed to protect your data and privacy while enabling seamless collaboration.</p><h3 id="research-start-resources" tabindex="-1">Research Start Resources <a class="header-anchor" href="#research-start-resources" aria-label="Permalink to &quot;Research Start Resources&quot;">​</a></h3><ul><li><p>Back to <a href="/research/">Research Section</a></p></li><li><p><a href="https://intellipedia.intelink.gov/wiki/Intel_Links_and_Library" target="_blank" rel="noreferrer">NIPR Linkbook</a> (Requires NIPR access)</p></li><li><p>SIPR Link: <a href="https://intellipedia.intelink.sgov.gov/wiki/Intel_Links_and_Library" target="_blank" rel="noreferrer">https://intellipedia.intelink.sgov.gov/wiki/Intel_Links_and_Library</a> (Requires SIPR access)</p></li></ul><h3 id="background-and-context" tabindex="-1">Background and Context <a class="header-anchor" href="#background-and-context" aria-label="Permalink to &quot;Background and Context&quot;">​</a></h3><p>The research toolkit fosters teamwork and facilitates a structured approach to investigations. Save a copy of these templates to your Cryptpad account as a template or duplicate them to get started on your research journey. Each template guides the research process through the different stages, ensuring organized and focused collaboration.</p><h3 id="collaboration-made-easy" tabindex="-1">Collaboration Made Easy <a class="header-anchor" href="#collaboration-made-easy" aria-label="Permalink to &quot;Collaboration Made Easy&quot;">​</a></h3><p>These templates are living documents that allow for simultaneous collaboration across your team, ensuring that everyone is working with the most current information. As your project progresses, the templates evolve with it, keeping all contributions synchronized and integrated into a cohesive research strategy.</p><h3 id="customization-is-key" tabindex="-1">Customization is Key <a class="header-anchor" href="#customization-is-key" aria-label="Permalink to &quot;Customization is Key&quot;">​</a></h3><p>These templates are not set in stone. Use them as flexible guidelines and modify them as needed to meet the specific requirements of your research project. Add or remove elements, adjust the layout, and tailor the content to suit your investigation&#39;s unique goals and challenges.</p><h3 id="continuous-improvement" tabindex="-1">Continuous Improvement <a class="header-anchor" href="#continuous-improvement" aria-label="Permalink to &quot;Continuous Improvement&quot;">​</a></h3><p>We value your feedback to continuously improve these tools. Share your experiences and suggestions with us through our <a href="http://url.irregular.chat/research-template-feedback" target="_blank" rel="noreferrer">Feedback Survey</a>. Your input helps us make these templates even more effective for future users.</p><h3 id="core-templates-overview" tabindex="-1">Core Templates Overview <a class="header-anchor" href="#core-templates-overview" aria-label="Permalink to &quot;Core Templates Overview&quot;">​</a></h3><p>Here is an overview of the core research templates available. Each is designed to support different stages of the research process.</p><h3 id="base-research-document" tabindex="-1">Base Research Document <a class="header-anchor" href="#base-research-document" aria-label="Permalink to &quot;Base Research Document&quot;">​</a></h3><p>The Base Research Document is the cornerstone of your investigation. It outlines your research strategy, defines objectives, and serves as a repository for questions and findings throughout the research project.</p><ul><li><a href="http://url.irregular.chat/research-template" target="_blank" rel="noreferrer">Base Research Document Template</a></li></ul><h3 id="research-tasks-kanban-board" tabindex="-1">Research Tasks (Kanban Board) <a class="header-anchor" href="#research-tasks-kanban-board" aria-label="Permalink to &quot;Research Tasks (Kanban Board)&quot;">​</a></h3><p>The Research Tasks Kanban Board is a visual and interactive tool for managing tasks throughout the research process. It helps you track the progress of each phase, from planning and data collection to analysis and reporting.</p><ul><li><a href="http://url.irregular.chat/research-template-tasks" target="_blank" rel="noreferrer">Research Tasks Kanban Board Template</a></li></ul><h3 id="structured-analytic-techniques-sats-sheets" tabindex="-1">Structured Analytic Techniques (SATs) (Sheets) <a class="header-anchor" href="#structured-analytic-techniques-sats-sheets" aria-label="Permalink to &quot;Structured Analytic Techniques (SATs) (Sheets)&quot;">​</a></h3><p>This template provides a collection of Structured Analytic Techniques (SATs) for methodical planning and analysis. SATs ensure rigor in your investigative process by promoting systematic thinking and reducing cognitive biases.</p><ul><li><p><a href="http://url.irregular.chat/research-template-sats" target="_blank" rel="noreferrer">SATs Sheets Template</a></p></li><li><p><a href="/general/structured-analytic-techniques-sats.html">SATs Guide</a></p></li></ul><h3 id="research-diagram-draw" tabindex="-1">Research Diagram (Draw) <a class="header-anchor" href="#research-diagram-draw" aria-label="Permalink to &quot;Research Diagram (Draw)&quot;">​</a></h3><p>Use this template to visualize complex data and relationships. Diagrams help clarify and communicate important aspects of your research by illustrating connections between different data points.</p><ul><li><a href="http://url.irregular.chat/research-template-diagram" target="_blank" rel="noreferrer">Research Diagram Template</a></li></ul><h3 id="research-log-sheets" tabindex="-1">Research Log (Sheets) <a class="header-anchor" href="#research-log-sheets" aria-label="Permalink to &quot;Research Log (Sheets)&quot;">​</a></h3><p>The Research Log template is a structured tool for recording and organizing data throughout your investigation. It is designed for comprehensive data collection, categorization, and retrieval to ensure no important information is lost.</p><ul><li><a href="http://url.irregular.chat/research-template-log" target="_blank" rel="noreferrer">Research Log Sheets Template</a></li></ul><h3 id="content-drop-off-form" tabindex="-1">Content Drop Off (Form) <a class="header-anchor" href="#content-drop-off-form" aria-label="Permalink to &quot;Content Drop Off (Form)&quot;">​</a></h3><p>This anonymous form allows you to collect information from a wide range of sources, feeding directly into your research. It simplifies the process of integrating new data into your ongoing investigation.</p><ul><li><a href="/">Drop-Off Form Template</a></li></ul><h3 id="how-to-use-these-templates" tabindex="-1">How to Use These Templates <a class="header-anchor" href="#how-to-use-these-templates" aria-label="Permalink to &quot;How to Use These Templates&quot;">​</a></h3><p>By utilizing these templates, you can ensure that your research is consistent, efficient, and thorough from start to finish. The templates are designed to guide you through every critical stage of the research process—planning, data collection, analysis, and reporting. Customize them as necessary to fit your specific project needs, and use them to maintain structure and focus throughout your investigation.</p>',36)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
